"""Extended fuzz: fuzzy positions, order/bond operators, 0-strand, origin-wraps.
Invariant: identical physical span set and part strands after flip+file roundtrip,
content preservation for uniformly-stranded features.
"""
import io, random, sys, warnings
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent / "source"))
from Bio.Seq import Seq, reverse_complement
from Bio.SeqFeature import (CompoundLocation, SeqFeature, SimpleLocation,
                            ExactPosition, BeforePosition, AfterPosition,
                            WithinPosition, BetweenPosition, OneOfPosition)
from Bio.SeqRecord import SeqRecord
from Bio import SeqIO

random.seed(99)
NT = "ACGT"

def rpos(L, is_start):
    kind = random.random()
    base = random.randint(0, L)
    if kind < 0.6:
        return ExactPosition(base)
    if kind < 0.75:
        return BeforePosition(base)
    if kind < 0.9:
        return AfterPosition(base)
    return WithinPosition(base, max(0, base - random.randint(0, 3)), min(L, base + random.randint(0, 3)))

def rand_record(idx):
    L = random.randint(40, 150)
    seq = "".join(random.choice(NT) for _ in range(L))
    feats = []
    for k in range(random.randint(1, 6)):
        nparts = random.randint(1, 4)
        parts = []
        for _ in range(nparts):
            a = random.randint(0, L - 2)
            b = random.randint(a + 1, L)
            if random.random() < 0.5:
                s, e = rpos(L, True), rpos(L, False)
                if s > e: s, e = e, s
                if s == e: e = s + 1
            else:
                s, e = ExactPosition(a), ExactPosition(b)
            st = random.choice([1, -1, None, 0])
            parts.append(SimpleLocation(s, e, st))
        op = random.choice(["join", "order"])
        loc = parts[0] if len(parts) == 1 else CompoundLocation(parts, op)
        feats.append(SeqFeature(loc, type="misc_feature", qualifiers={"label": [f"f{k}"]}))
    return SeqRecord(Seq(seq), id=f"r{idx}", name=f"r{idx}",
                     annotations={"molecule_type": "DNA",
                                  "topology": random.choice(["circular", "linear"])},
                     features=feats)

def canonical_part(p):
    return (p.start, p.end, p.strand)

def posflip(pos, L):
    from Bio.SeqFeature import (ExactPosition, WithinPosition, BetweenPosition,
                                BeforePosition, AfterPosition, OneOfPosition, UnknownPosition, UncertainPosition)
    if isinstance(pos, UnknownPosition): return pos
    if isinstance(pos, OneOfPosition):
        return OneOfPosition(L - int(pos), [posflip(c, L) for c in reversed(pos.position_choices)])
    if isinstance(pos, WithinPosition):
        return WithinPosition(L - int(pos), L - pos._right, L - pos._left)
    if isinstance(pos, BetweenPosition):
        return BetweenPosition(L - int(pos), L - pos._right, L - pos._left)
    if isinstance(pos, BeforePosition):
        return AfterPosition(L - int(pos))
    if isinstance(pos, AfterPosition):
        return BeforePosition(L - int(pos))
    return pos.__class__(L - int(pos))

def part_flip(p, L):
    st = {-1: 1, 1: -1, 0: 0, None: None}[p.strand]
    return SimpleLocation(posflip(p.end, L), posflip(p.start, L), st)

def expected_flip(loc, L, operator):
    if isinstance(loc, SimpleLocation):
        return part_flip(loc, L)
    return CompoundLocation([part_flip(p, L) for p in loc.parts], operator)

reports = []
N = 800
for i in range(N):
    rec = rand_record(i)
    L = len(rec.seq)
    by = {f.qualifiers["label"][0]: f for f in rec.features}
    fl = rec.reverse_complement(id=rec.id)
    fl.annotations["molecule_type"] = "DNA"
    fl.annotations["topology"] = rec.annotations["topology"]
    fby = {f.qualifiers["label"][0]: f for f in fl.features}
    for lb, sf in by.items():
        ef = expected_flip(sf.location, L, getattr(sf.location, "operator", None))
        got = fby[lb].location
        if repr(got) != repr(ef):
            reports.append(("INMEM", rec.id, lb, repr(ef), repr(got)))
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            buf = io.StringIO(); SeqIO.write([fl], buf, "genbank")
            buf.seek(0); dl = next(SeqIO.parse(buf, "genbank"))
    except Exception as e:
        reports.append(("IO_ERROR", rec.id, type(e).__name__, str(e)))
        continue
    dby = {f.qualifiers["label"][0]: f for f in dl.features}
    for lb, sf in by.items():
        ef = expected_flip(sf.location, L, getattr(sf.location, "operator", None))
        def key(loc):
            return sorted((int(p.start), int(p.end)) for p in loc.parts)
        if key(dby[lb].location) != sorted((int(p.start), int(p.end)) for p in ef.parts):
            reports.append(("SPANSET", rec.id, lb, str(ef), str(dby[lb].location)))

from collections import Counter
print("records:", N, "reports:", len(reports), Counter(r[0] for r in reports))
seen = Counter()
for r in reports:
    if seen[r[0]] < 5:
        print(r)
        seen[r[0]] += 1

