"""Differential fuzz: delivered record vs independently simulated write->parse
normalization N(flip(x)) under documented INSDC + Biopython rules."""
import io, random, sys, warnings
from pathlib import Path
sys.path.insert(0, str(Path(__file__).parent / "source"))

from Bio.Seq import Seq
from Bio.SeqFeature import (CompoundLocation, SeqFeature, SimpleLocation,
                            ExactPosition, BeforePosition, AfterPosition,
                            WithinPosition, OneOfPosition)
from Bio.SeqRecord import SeqRecord
from Bio import SeqIO

random.seed(31337)

def randpos(L, side):
    r = random.random()
    if r < 0.55: return ExactPosition(random.randint(0, L))
    if r < 0.7: return BeforePosition(random.randint(0, L))
    if r < 0.85: return AfterPosition(random.randint(0, L))
    base = random.randint(0, L)
    left = random.randint(0, base); right = random.randint(base, min(L, base + 3))
    return WithinPosition(right if random.random() < .5 else left, left, right)

def randloc(L):
    n = random.randint(1, 4)
    parts = []
    for _ in range(n):
        s, e = randpos(L, "s"), randpos(L, "e")
        if s > e: s, e = e, s
        if s == e: e = s + 1 if e < L else s - 1
        if s > e: e, s = s, e
        parts.append(SimpleLocation(s, e, random.choice([1, -1, None, 0])))
    if n == 1: return parts[0]
    return CompoundLocation(parts, random.choice(["join", "order"]))

def flippos(p, L):
    if isinstance(p, OneOfPosition):
        return OneOfPosition(L - int(p), [flippos(c, L) for c in reversed(p.position_choices)])
    if isinstance(p, WithinPosition):
        return WithinPosition(L - int(p), L - p._right, L - p._left)
    if isinstance(p, BeforePosition): return AfterPosition(L - int(p))
    if isinstance(p, AfterPosition): return BeforePosition(L - int(p))
    return p.__class__(L - int(p))

def flipped(loc, L):
    fs = {-1: 1, 1: -1, 0: 0, None: None}
    if isinstance(loc, CompoundLocation):
        return CompoundLocation(
            [SimpleLocation(flippos(p._end, L), flippos(p._start, L), fs[p.strand]) for p in loc.parts],
            loc.operator)
    return SimpleLocation(flippos(loc._end, L), flippos(loc._start, L), fs[loc.strand])

def norm_after_parse(loc):
    """Simulate write->genbank->parse on an already-flipped location object."""
    def sim_part(p, compound_minus):
        strand = p.strand
        if compound_minus:
            strand = -1
        else:
            strand = -1 if strand == -1 else 1
        return SimpleLocation(p._start, p._end, strand)
    if isinstance(loc, CompoundLocation):
        if loc.strand == -1:
            # complement(op(reversed parts)) -> parse reverses back; identity
            return CompoundLocation([sim_part(p, True) for p in loc.parts], loc.operator)
        return CompoundLocation([sim_part(p, False) for p in loc.parts], loc.operator)
    return sim_part(loc, False)

bad = 0
N = 2000
for i in range(N):
    L = random.randint(30, 150)
    seq = "".join(random.choice("ACGT") for _ in range(L))
    rec = SeqRecord(Seq(seq), id=f"r{i}", annotations={"molecule_type": "DNA",
                    "topology": random.choice(["circular", "linear"])})
    rec.features = [SeqFeature(randloc(L), type="misc_feature", qualifiers={"label":[f"f{k}"]})
                    for k in range(random.randint(1, 4))]
    fl = rec.reverse_complement(id=f"r{i}")
    fl.annotations["molecule_type"] = "DNA"
    fl.annotations["topology"] = rec.annotations["topology"]
    src_by = {f.qualifiers["label"][0]: f for f in rec.features}
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        buf = io.StringIO(); SeqIO.write([fl], buf, "genbank"); buf.seek(0)
        dl = SeqIO.read(buf, "genbank")
    dl_by = {f.qualifiers["label"][0]: f for f in dl.features}
    for lb, sf in src_by.items():
        exp = norm_after_parse(flipped(sf.location, L))
        got = dl_by[lb].location
        if repr(got) != repr(exp):
            bad += 1
            if bad <= 10:
                print("DIVERGENCE", i, lb)
                print("  src:", repr(sf.location))
                print("  exp:", repr(exp))
                print("  got:", repr(got))
print("records:", N, "divergences:", bad)
